//! Resolved text and box styles. Values come from a theme (never chosen
//! here); this module turns them into GPUI text styles for the containers
//! GPUI Kit's text leaves inherit from, using the editor faces generated by
//! tools/import-editor-fonts.py.
use gpui::{
    FontFallbacks, FontFeatures, FontStyle, FontWeight, Rgba, SharedString, StyleRefinement,
    TextStyleRefinement, px,
};

/// The family GPUI Kit's inline-code mark uses while editor text is built:
/// Geist Mono with 875 units per em, so Kit's 0.875 code size renders the
/// product's full-size inline code.
pub const INLINE_CODE_FAMILY: &str = "PuppyOne Geist Mono Inline";

/// Weights generated for each editor family (assets/fonts/editor).
const SANS_WEIGHTS: [u16; 7] = [400, 450, 500, 600, 625, 650, 700];
const SANS_OBLIQUE: [u16; 6] = [400, 500, 600, 625, 650, 700];
const MONO_WEIGHTS: [u16; 4] = [400, 500, 600, 700];
const MONO_OBLIQUE: [u16; 2] = [500, 600];
/// The product's CJK/emoji fallbacks after Geist (`--po-md-content-font`).
const FALLBACKS: [&str; 4] = [
    "PingFang SC",
    "Hiragino Sans GB",
    "Apple Color Emoji",
    "Helvetica Neue",
];

/// Embedded editor faces, registered once at startup.
pub fn font_bytes() -> Vec<std::borrow::Cow<'static, [u8]>> {
    macro_rules! faces {
        ($($name:literal),* $(,)?) => {
            vec![$(std::borrow::Cow::Borrowed(include_bytes!(concat!("../../../assets/fonts/editor/", $name)) as &[u8])),*]
        };
    }
    faces!(
        "geist-sans-400.ttf",
        "geist-sans-450.ttf",
        "geist-sans-500.ttf",
        "geist-sans-600.ttf",
        "geist-sans-625.ttf",
        "geist-sans-650.ttf",
        "geist-sans-700.ttf",
        "geist-sans-400-oblique.ttf",
        "geist-sans-500-oblique.ttf",
        "geist-sans-600-oblique.ttf",
        "geist-sans-625-oblique.ttf",
        "geist-sans-650-oblique.ttf",
        "geist-sans-700-oblique.ttf",
        "geist-sans-500-bold.ttf",
        "geist-sans-500-bold-oblique.ttf",
        "geist-mono-400.ttf",
        "geist-mono-500.ttf",
        "geist-mono-600.ttf",
        "geist-mono-700.ttf",
        "geist-mono-500-oblique.ttf",
        "geist-mono-600-oblique.ttf",
        "geist-mono-inline.ttf",
        "geist-mono-inline-oblique.ttf",
        "geist-mono-inline-bold.ttf",
        "geist-mono-inline-bold-oblique.ttf",
    )
}

fn nearest(available: &[u16], weight: f32) -> u16 {
    *available
        .iter()
        .min_by(|a, b| {
            ((**a as f32) - weight)
                .abs()
                .total_cmp(&((**b as f32) - weight).abs())
        })
        .unwrap()
}

/// CSS `line-height`: a number is inherited as a factor of each element's
/// own font size; a length is inherited as is.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum LineHeight {
    Factor(f32),
    Px(f32),
}

impl LineHeight {
    pub fn resolve(self, font_size: f32) -> f32 {
        match self {
            Self::Factor(f) => f * font_size,
            Self::Px(v) => v,
        }
    }
}

/// The inherited text style of a box (what CSS gives `.cm-line`).
#[derive(Clone, Debug, PartialEq)]
pub struct TextStyle {
    pub size: f32,
    pub weight: f32,
    pub italic: bool,
    pub mono: bool,
    pub color: Rgba,
    /// `font-variant-numeric: tabular-nums`.
    pub tabular: bool,
    pub line_height: LineHeight,
}

impl TextStyle {
    /// One generated family per weight; Kit's bold mark (700) selects the
    /// family's Bold slot, which carries the product's strong weight.
    pub fn family(&self) -> SharedString {
        if self.mono {
            let w = nearest(
                if self.italic {
                    &MONO_OBLIQUE
                } else {
                    &MONO_WEIGHTS
                },
                self.weight,
            );
            format!("PuppyOne Geist Mono {w}").into()
        } else {
            let w = nearest(
                if self.italic {
                    &SANS_OBLIQUE
                } else {
                    &SANS_WEIGHTS
                },
                self.weight,
            );
            format!("PuppyOne Geist {w}").into()
        }
    }
    pub fn line_height_px(&self) -> f32 {
        self.line_height.resolve(self.size)
    }
    /// CSS `ch`: the advance of "0" in the primary face.
    pub fn ch(&self) -> f32 {
        zero_advance(self.mono, self.italic, self.weight) * self.size
    }
    /// The text refinement a container applies so Kit leaves inherit it.
    pub fn refinement(&self) -> TextStyleRefinement {
        TextStyleRefinement {
            color: Some(self.color.into()),
            font_family: Some(self.family()),
            font_features: Some(if self.tabular {
                FontFeatures(std::sync::Arc::new(vec![("tnum".into(), 1)]))
            } else {
                FontFeatures::default()
            }),
            font_fallbacks: Some(FontFallbacks::from_fonts(
                FALLBACKS.iter().map(|s| s.to_string()).collect(),
            )),
            font_size: Some(px(self.size).into()),
            line_height: Some(px(self.line_height_px()).into()),
            // The family already has the weight; the CSS weight still steers
            // system fallback faces (PingFang SC Medium).
            font_weight: Some(FontWeight(self.weight)),
            font_style: Some(if self.italic {
                FontStyle::Italic
            } else {
                FontStyle::Normal
            }),
            ..Default::default()
        }
    }
    /// Apply as an element's inherited text style.
    pub fn apply(&self, style: &mut StyleRefinement) {
        style.text = self.refinement();
    }
}

/// Advance of "0" per em of each generated face (manifest `zeroAdvance`).
fn zero_advance(mono: bool, italic: bool, weight: f32) -> f32 {
    static TABLE: std::sync::OnceLock<std::collections::HashMap<String, f32>> =
        std::sync::OnceLock::new();
    let table = TABLE.get_or_init(|| {
        let manifest: serde_json::Value =
            serde_json::from_str(include_str!("../../../assets/fonts/editor/manifest.json"))
                .expect("font manifest");
        manifest["zeroAdvance"]
            .as_object()
            .map(|m| {
                m.iter()
                    .filter_map(|(k, v)| Some((k.clone(), v.as_f64()? as f32)))
                    .collect()
            })
            .unwrap_or_default()
    });
    let (slug, weights): (&str, &[u16]) = if mono {
        ("mono", if italic { &MONO_OBLIQUE } else { &MONO_WEIGHTS })
    } else {
        ("sans", if italic { &SANS_OBLIQUE } else { &SANS_WEIGHTS })
    };
    let w = nearest(weights, weight);
    let suffix = if italic { "-oblique" } else { "" };
    table
        .get(&format!("geist-{slug}-{w}{suffix}.ttf"))
        .copied()
        .unwrap_or(0.6)
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Edges {
    pub top: f32,
    pub right: f32,
    pub bottom: f32,
    pub left: f32,
}

impl Edges {
    pub fn new(top: f32, right: f32, bottom: f32, left: f32) -> Self {
        Self {
            top,
            right,
            bottom,
            left,
        }
    }
    pub fn all(v: f32) -> Self {
        Self::new(v, v, v, v)
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rect {
    pub x: f32,
    pub y: f32,
    pub width: f32,
    pub height: f32,
}

impl Rect {
    pub fn new(x: f32, y: f32, width: f32, height: f32) -> Self {
        Self {
            x,
            y,
            width,
            height,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Align {
    Start,
    Center,
    End,
}

/// Absolutely positioned decoration inside a box (CSS backgrounds, borders
/// and pseudo-elements), relative to the box's border-box origin.
#[derive(Clone, Debug, PartialEq)]
pub enum Paint {
    /// A box: background, per-corner radii and a uniform border.
    Quad {
        rect: Rect,
        background: Option<Rgba>,
        radii: [f32; 4],
        border: f32,
        border_color: Option<Rgba>,
    },
    /// Text that is not document source (`::before` list markers), laid out
    /// on one row inside `rect`, centred vertically, aligned horizontally.
    Label {
        rect: Rect,
        text: SharedString,
        style: TextStyle,
        align: Align,
    },
    /// A filled polygon (e.g. the rotated check of a task box).
    Polygon {
        points: Vec<(f32, f32)>,
        color: Rgba,
    },
}

impl Paint {
    pub fn fill(rect: Rect, color: Rgba) -> Self {
        Self::Quad {
            rect,
            background: Some(color),
            radii: [0.; 4],
            border: 0.,
            border_color: None,
        }
    }
}

/// The complete style of one `.cm-line` box.
#[derive(Clone, Debug, PartialEq)]
pub struct LineStyle {
    /// Inherited text style (font, size, colour, line height).
    pub text: TextStyle,
    pub padding: Edges,
    /// Border widths, outside the padding (`border-left` of quotes).
    pub border: Edges,
    pub border_color: Option<Rgba>,
    pub background: Option<Rgba>,
    /// `box-shadow: inset 0 -Npx color`: a rule along the bottom edge.
    pub inset_bottom: Option<(f32, Rgba)>,
    /// A line-through over the whole line's text (`.cm-md-task-checked`).
    pub strike: bool,
    /// `white-space: pre` (no wrapping), as in code panels.
    pub nowrap: bool,
    /// Painted above the text (markers, checkboxes).
    pub overlays: Vec<Paint>,
    /// Interactive areas (task checkboxes): rect and the format command.
    pub hotspots: Vec<(Rect, super::command::Command)>,
}

impl LineStyle {
    pub fn new(text: TextStyle) -> Self {
        Self {
            text,
            padding: Edges::default(),
            border: Edges::default(),
            border_color: None,
            background: None,
            inset_bottom: None,
            strike: false,
            nowrap: false,
            overlays: Vec::new(),
            hotspots: Vec::new(),
        }
    }
}
